package gin

import (
	"errors"
	"fmt"
	"testing"
)

type scratchErr string

func (e scratchErr) Error() string { return string(e) }

func TestScratchUnwrap(t *testing.T) {
	inner := scratchErr("some error")

	t.Run("ptr-wrap-is", func(t *testing.T) {
		err := fmt.Errorf("wrapped: %w", &Error{Err: inner, Type: ErrorTypeAny})
		if !errors.Is(err, inner) {
			t.Error("ptr wrap: errors.Is failed")
		}
		var te scratchErr
		if !errors.As(err, &te) {
			t.Error("ptr wrap: errors.As failed")
		}
	})

	t.Run("val-wrap-is", func(t *testing.T) {
		err := fmt.Errorf("wrapped: %w", Error{Err: inner, Type: ErrorTypeAny})
		if !errors.Is(err, inner) {
			t.Error("val wrap: errors.Is failed")
		}
		var te scratchErr
		if !errors.As(err, &te) {
			t.Error("val wrap: errors.As failed")
		}
	})

	t.Run("direct-ptr", func(t *testing.T) {
		if !errors.Is(&Error{Err: inner, Type: ErrorTypeAny}, inner) {
			t.Error("direct ptr: errors.Is failed")
		}
		var te scratchErr
		if !errors.As(&Error{Err: inner, Type: ErrorTypeAny}, &te) {
			t.Error("direct ptr: errors.As failed")
		}
	})

	t.Run("direct-val", func(t *testing.T) {
		if !errors.Is(Error{Err: inner, Type: ErrorTypeAny}, inner) {
			t.Error("direct val: errors.Is failed")
		}
		var te scratchErr
		if !errors.As(Error{Err: inner, Type: ErrorTypeAny}, &te) {
			t.Error("direct val: errors.As failed")
		}
	})

	t.Run("unwrap-eq", func(t *testing.T) {
		g := &Error{Err: inner, Type: ErrorTypeAny}
		if errors.Unwrap(g) != error(inner) {
			t.Error("unwrap mismatch")
		}
	})

	t.Run("nested", func(t *testing.T) {
		err := fmt.Errorf("a: %w", fmt.Errorf("b: %w", &Error{Err: inner, Type: ErrorTypeAny}))
		if !errors.Is(err, inner) {
			t.Error("nested: errors.Is failed")
		}
	})
}
EOF
go test -run TestScratchUnwrap -v . 2>&1 | head -60

