package gin

import (
	"errors"
	"fmt"
	"testing"
)

type scratchErr2 string

func (e scratchErr2) Error() string { return string(e) }

func TestScratch2(t *testing.T) {
	inner := scratchErr2("some error")
	ginErr := &Error{Err: inner, Type: ErrorTypeAny}

	// errors.As into *Error
	var target *Error
	if !errors.As(fmt.Errorf("w: %w", ginErr), &target) {
		t.Error("As into *Error failed")
	}
	// errors.As into error interface
	var target2 error
	if !errors.As(fmt.Errorf("w: %w", ginErr), &target2) {
		t.Error("As into error failed")
	}
	// errors.Is with gin error as target
	if !errors.Is(fmt.Errorf("w: %w", ginErr), ginErr) {
		t.Error("Is with gin err target failed")
	}
	// errors.Is with value gin error as target
	if !errors.Is(fmt.Errorf("w: %w", ginErr), Error{Err: inner, Type: ErrorTypeAny}) {
		t.Log("Is with value gin err target failed (expected: no Is method)")
	}
}
EOF
