package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func mkCtx(accept string) *Context {
	c, _ := CreateTestContext(httptest.NewRecorder())
	c.Request, _ = http.NewRequest("POST", "", nil)
	if accept != "" {
		c.Request.Header.Add("Accept", accept)
	}
	return c
}

func TestZZScratchNegotiate(t *testing.T) {
	cases := []struct {
		accept  string
		offers  []string
	}{
		{"text/html; charset=utf-8, application/json", []string{MIMEHTML, MIMEJSON}},
		{"text/html; charset=utf-8, application/json", []string{MIMEJSON, MIMEHTML}},
		{"text/html; charset=utf-8, application/json", []string{MIMEXML}},
		{"text/html", []string{"text"}},
		{"application/json", []string{"application"}},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{MIMEJSON, MIMEXML}},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{MIMEXML, MIMEHTML}},
		{"text/html,application/xhtml+xml,application/xml;q=0.9;q=0.8", []string{MIMEJSON}},
		{"*/*", []string{"text/*"}},
		{"text/*", []string{MIMEHTML}},
		{"text/*", []string{MIMEJSON}},
		{"", []string{MIMEJSON, MIMEXML}},
		{"application/json", []string{"application/json; charset=utf-8"}},
	}
	for _, tc := range cases {
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					t.Errorf("PANIC accept=%q offers=%v: %v", tc.accept, tc.offers, rec)
				}
			}()
			c := mkCtx(tc.accept)
			got := c.NegotiateFormat(tc.offers...)
			t.Logf("accept=%q offers=%v -> %q", tc.accept, tc.offers, got)
		}()
	}
}
EOF
